-- crash-edit/lock-crash
-- Locks one crash for the rest of the transaction, so two edits at once are handled one after the other.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

select "id", "slug", "status", "merged_into_id", "title_en", "title_np", "occurred_on", "occurred_time", "location", "location_precision", "place_name_en", "place_name_np", "province_id", "district_id", "local_unit_id", "deaths", "injured_total", "created_via", "verification_level", "version", "created_at", "updated_at"
from "crashes"
where "crashes"."id" = $1
limit $2 for update;
